<?php ob_start(); $isAdmin = $user['role'] === 'pengurus'; $activeBorrowings = array_filter($transactions, fn(array $item): bool => $item['status'] === 'Dipinjam'); ?>
<section class="stats"><div><span>Total koleksi</span><strong><?= $stats['total'] ?></strong><small>judul terdaftar</small></div><div><span>Buku tersedia</span><strong class="green"><?= $stats['available'] ?></strong><small>siap dipinjam</small></div><div><span>Sedang dipinjam</span><strong class="orange"><?= $stats['borrowed'] ?></strong><small>perlu dipantau</small></div><div><span>Total transaksi</span><strong class="blue"><?= $stats['transactions'] ?></strong><small>seluruh riwayat</small></div></section>
<section class="panel" id="catalog"><div class="panel-head"><div><p class="eyebrow">KATALOG</p><h2><?= $isAdmin ? 'Manajemen koleksi' : 'Temukan buku berikutnya' ?></h2></div><?php if ($isAdmin): ?><button class="button primary" onclick="document.getElementById('book-form').scrollIntoView({behavior:'smooth'})">+ Tambah buku</button><?php endif; ?></div><div class="book-grid"><?php foreach ($books as $book): ?><article class="book-card"><div class="book-cover"><span><?= e(substr($book['category'], 0, 2)) ?></span><b><?= e($book['id']) ?></b></div><div class="book-info"><span class="tag"><?= e($book['category']) ?></span><h3><?= e($book['title']) ?></h3><p><?= e($book['author']) ?> · <?= e($book['year']) ?></p><div class="book-foot"><span class="status <?= $book['status'] === 'Tersedia' ? 'available' : 'borrowed' ?>"><?= e($book['status']) ?></span><?php if (!$isAdmin && $book['status'] === 'Tersedia'): ?><form method="post"><input type="hidden" name="_csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="action" value="borrow"><input type="hidden" name="bookId" value="<?= e($book['id']) ?>"><button class="mini-button" type="submit">Pinjam</button></form><?php elseif ($isAdmin): ?><form method="post" class="inline-form"><input type="hidden" name="_csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="action" value="delete_book"><input type="hidden" name="id" value="<?= e($book['id']) ?>"><button class="mini-button danger" type="submit" <?= $book['status'] === 'Dipinjam' ? 'disabled' : '' ?>>Hapus</button></form><?php endif; ?></div></div></article><?php endforeach; ?></div></section>
<?php if ($isAdmin): ?><section class="panel compact" id="book-form"><div class="panel-head"><div><p class="eyebrow">KATALOG</p><h2>Tambah buku baru</h2></div></div><form method="post" class="book-form"><input type="hidden" name="_csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="action" value="save_book"><label>Judul<input name="title" required></label><label>Pengarang<input name="author" required></label><label>Kategori<input name="category" required></label><label>Tahun<input name="year" type="number" min="1900" max="2099" required></label><button class="button primary" type="submit">Simpan buku</button></form></section><?php endif; ?>
<section class="panel" id="transactions"><div class="panel-head"><div><p class="eyebrow">AKTIVITAS</p><h2><?= $isAdmin ? 'Seluruh transaksi' : 'Buku yang sedang Anda pinjam' ?></h2></div><span class="counter"><?= count($transactions) ?> catatan</span></div><?php if (!$transactions): ?><div class="empty">Belum ada transaksi peminjaman.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Transaksi</th><th>Buku</th><th><?= $isAdmin ? 'Peminjam' : 'Tanggal pinjam' ?></th><th>Jatuh tempo</th><th>Status</th><?php if ($isAdmin): ?><th>Aksi</th><?php endif; ?></tr></thead><tbody><?php foreach ($transactions as $trx): ?><tr><td><strong><?= e($trx['id']) ?></strong></td><td><?= e($trx['bookTitle']) ?></td><td><?= $isAdmin ? e($trx['userName']) : e($trx['borrowDate']) ?></td><td><?= e($trx['dueDate']) ?></td><td><span class="status <?= $trx['status'] === 'Dipinjam' ? 'borrowed' : 'available' ?>"><?= e($trx['status']) ?></span></td><?php if ($isAdmin): ?><td><?php if ($trx['status'] === 'Dipinjam'): ?><form method="post"><input type="hidden" name="_csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="action" value="return_book"><input type="hidden" name="id" value="<?= e($trx['id']) ?>"><button class="mini-button" type="submit">Tandai kembali</button></form><?php endif; ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php $content = ob_get_clean(); $title = $isAdmin ? 'Panel Pengurus' : 'Ruang Baca'; $heading = $isAdmin ? 'Kelola perpustakaan dengan tenang.' : 'Baca lebih banyak, satu buku sekali waktu.'; require __DIR__ . '/../layout.php'; ?>
